// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { LARGE_GRAPH_NODES } from "../../../main/frontend/graph-explorer/explorer-config.ts";
import { ORGANIC_LIMIT } from "../../../main/frontend/graph-explorer/graph-layout-engine.ts";
import {
  describeLayoutDuration,
  describeRelayoutChanges,
  estimateLayoutMs,
  laidOutGraph,
  MULTILEVEL_LAYOUT_NODES,
  readLayoutTiming,
  relayoutSuggestion,
  ROUTED_LAYOUT_NODES,
  writeLayoutTiming,
} from "../../../main/frontend/graph-explorer/relayout-suggestion.ts";

const link = (id, source, target) => ({ id, source, target, predicate: "p", label: "p" });

/** A path of `nodes` nodes from `n<from>`, each linked to the one before. */
function chain(nodes, from = 0) {
  const ids = Array.from({ length: nodes }, (_, index) => `n${from + index}`);
  return {
    revision: 1,
    nodes: ids.map((id) => ({ id, label: id, kind: "iri" })),
    edges: ids.slice(1).map((id, index) => link(`${ids[index]}->${id}`, ids[index], id)),
  };
}

const withNodes = (graph, count) => {
  const last = graph.nodes.length;
  const added = chain(count + 1, last - 1);
  return { ...graph, nodes: [...graph.nodes, ...added.nodes.slice(1)], edges: [...graph.edges, ...added.edges] };
};

test("a graph drawn as it was laid out does not ask for a new layout", () => {
  const graph = chain(30);
  assert.equal(relayoutSuggestion(laidOutGraph(graph), graph), null);
});

test("nodes and links added since the last layout ask for a new one, and say how many", () => {
  const graph = chain(30);
  const grown = withNodes(graph, 6);
  assert.deepEqual(relayoutSuggestion(laidOutGraph(graph, "hierarchy"), grown),
    { nodes: 6, links: 6, mode: "hierarchy" });
});

test("a change that is small for the size of the graph does not ask for a new layout", () => {
  const graph = chain(200);
  assert.equal(relayoutSuggestion(laidOutGraph(graph), withNodes(graph, 2)), null);
  assert.notEqual(relayoutSuggestion(laidOutGraph(graph), withNodes(graph, 25)), null);
});

test("hidden nodes and their links count; a graph back as it was laid out asks for nothing", () => {
  const graph = chain(30);
  const laidOut = laidOutGraph(graph);
  const hidden = { ...graph, nodes: graph.nodes.slice(0, 24), edges: graph.edges.slice(0, 23) };
  assert.deepEqual(relayoutSuggestion(laidOut, hidden), { nodes: 6, links: 6, mode: "network" });
  assert.equal(relayoutSuggestion(laidOut, { ...graph, revision: 9 }), null);
});

test("links found between the nodes already drawn count too", () => {
  const graph = chain(20);
  const linked = {
    ...graph,
    edges: [...graph.edges, ...[0, 2, 4, 6, 8, 10].map((index) => link(`x${index}`, `n${index}`, `n${19 - index}`))],
  };
  assert.deepEqual(relayoutSuggestion(laidOutGraph(graph), linked), { nodes: 0, links: 6, mode: "network" });
});

test("a graph of the same size is expected to take as long as its last layout", () => {
  assert.equal(estimateLayoutMs({ nodes: 120, links: 300, durationMs: 800 }, 120, 300), 800);
});

/**
 * Layout times measured with the engine alone (`computeGraphLayout` in Node), as the page sees them: its worker adds
 * about 50 ms to every layout (a 1-node layout took 60 ms in the browser).
 */
const onPage = (engineMs) => engineMs + 50;

test("a larger graph is expected to take longer, in proportion to how long the last layout took", () => {
  // Measured: a 50-node graph with 111 links took 53 ms, the same kind of graph with 100 nodes and 255 links 263 ms.
  const estimate = estimateLayoutMs({ nodes: 50, links: 111, durationMs: onPage(53) }, 100, 255);
  assert.ok(estimate > onPage(263) / 2 && estimate < onPage(263) * 2, `${estimate} ms`);
  assert.equal(estimateLayoutMs({ nodes: 50, links: 111, durationMs: 2 * onPage(53) }, 100, 255), 2 * estimate);
  assert.ok(estimateLayoutMs({ nodes: 50, links: 111, durationMs: onPage(53) }, 40, 80) < onPage(53));
});

test("a last layout of a few nodes, mostly the cost of starting one, does not inflate the estimate", () => {
  // Measured in the browser: 1 node took 60 ms, then 251 nodes and 250 links 343 ms.
  const estimate = estimateLayoutMs({ nodes: 1, links: 0, durationMs: 60 }, 251, 250);
  assert.ok(estimate > 343 / 2 && estimate < 343 * 2, `${estimate} ms`);
});

test("the estimate follows the engines the layout uses at each size", () => {
  assert.equal(ROUTED_LAYOUT_NODES, LARGE_GRAPH_NODES, "arrows are routed below the large-graph canvas's size");
  assert.equal(MULTILEVEL_LAYOUT_NODES, ORGANIC_LIMIT, "the multilevel engine takes over past the organic one's limit");
  // Measured: 1,400 nodes took 3,066 ms with the organic engine, 1,600 nodes 31 ms with the multilevel one.
  const multilevel = estimateLayoutMs({ nodes: 1400, links: 4300, durationMs: onPage(3066) }, 1600, 4865);
  assert.ok(multilevel > onPage(31) / 3 && multilevel < onPage(31) * 3, `${multilevel} ms`);
  // Measured: 499 nodes with routed arrows took 1,959 ms, 650 nodes without them 690 ms.
  const unrouted = estimateLayoutMs({ nodes: 499, links: 1512, durationMs: onPage(1959) }, 650, 2017);
  assert.ok(unrouted > onPage(690) / 3 && unrouted < onPage(690) * 3, `${unrouted} ms`);
});

test("the suggestion says what changed", () => {
  assert.equal(describeRelayoutChanges({ nodes: 6, links: 1, mode: "network" }),
    "6 nodes and 1 link were added or taken away");
  assert.equal(describeRelayoutChanges({ nodes: 1, links: 0, mode: "network" }), "1 node was added or taken away");
  assert.equal(describeRelayoutChanges({ nodes: 0, links: 4, mode: "network" }), "4 links were added or taken away");
});

test("the estimate reads as a rough duration", () => {
  assert.equal(describeLayoutDuration(0), "under a second");
  assert.equal(describeLayoutDuration(400), "under a second");
  assert.equal(describeLayoutDuration(1400), "about 1 s");
  assert.equal(describeLayoutDuration(2600), "about 3 s");
  assert.equal(describeLayoutDuration(23_000), "about 25 s");
  assert.equal(describeLayoutDuration(95_000), "about 2 min");
});

test("the last layout's time is kept per layout in this browser, and storage that fails keeps nothing", () => {
  const items = new Map();
  const storage = { getItem: (key) => items.get(key) ?? null, setItem: (key, value) => items.set(key, value) };
  assert.equal(readLayoutTiming(storage, "network"), undefined);
  writeLayoutTiming(storage, "network", { nodes: 30, links: 40, durationMs: 25 });
  assert.deepEqual(readLayoutTiming(storage, "network"), { nodes: 30, links: 40, durationMs: 25 });
  assert.equal(readLayoutTiming(storage, "square"), undefined);
  for (const value of ["{", '{"nodes":"30"}', '{"nodes":0,"links":0,"durationMs":-1}']) {
    items.set([...items.keys()][0], value);
    assert.equal(readLayoutTiming(storage, "network"), undefined, value);
  }
  const failing = { getItem: () => { throw new Error("denied"); }, setItem: () => { throw new Error("denied"); } };
  assert.equal(readLayoutTiming(failing, "network"), undefined);
  assert.doesNotThrow(() => writeLayoutTiming(failing, "network", { nodes: 1, links: 0, durationMs: 1 }));
  assert.equal(readLayoutTiming(undefined, "network"), undefined);
});
